// Message handlers with verification primitives
import type { MessageBus } from "@fairfox/polly/message-bus";
import { ensures, hasLength, requires, stateConstraint } from "@fairfox/polly/verify";
import type { TodoMessages } from "../shared/messages";
import type { Todo } from "../shared/types";
import { filter, generateId, maxTodos, theme, todos, user } from "./state";

// State constraint: logged-out users must have guest role.
// Prunes impossible states like (loggedIn=false, role="admin") from TLC exploration.
// Declared at module scope (a verify-only, runtime no-op) so it is extracted the
// same way whether the handlers are wired by the extension entry or the BDD world.
stateConstraint(
  "LoggedOutIsGuest",
  () => user.value.loggedIn === true || user.value.role === "guest"
);

/**
 * Register every todo-list handler on a bus.
 *
 * This is the single composite helper the real background entry (index.ts) and
 * the BDD world (features/steps.ts) BOTH call — neither hand-wires the bus, so
 * a gap in the factory path can't hide behind a test that compensates for it
 * (the polly#57 lesson). The `bus.on(...)` calls and their requires/ensures are
 * unchanged, so the verify extractor reads them exactly as before.
 */
export function registerTodoHandlers(bus: MessageBus<TodoMessages>): void {
  // User Authentication

  bus.on(
    "USER_LOGIN",
    (payload: { userId: string; name: string; role: "user" | "admin" | "guest" }) => {
      // Preconditions - user must not already be logged in. The role precondition
      // narrows payload.role's domain so the role postcondition below is provable.
      requires(user.value.loggedIn === false, "User must not be logged in");
      requires(payload.userId !== null, "User ID must be provided");
      requires(payload.role !== "guest", "Login role must not be guest");

      // State changes - using reactive signals with automatic sync
      user.value = {
        loggedIn: true,
        id: payload.userId,
        name: payload.name,
        role: payload.role,
      };

      // Postconditions - verify state was updated correctly. Both writes are now
      // surfaced as modeled assignments (loggedIn as a literal, role traced
      // through payload.role into the user.role enum), so TLC's Assert checks
      // are honest postconditions rather than documentation.
      ensures(user.value.loggedIn === true, "User must be logged in after login");
      ensures(user.value.role !== "guest", "User must have non-guest role");

      return { success: true, user: user.value };
    }
  );

  bus.on("USER_LOGOUT", () => {
    // Precondition - user must be logged in to logout
    requires(user.value.loggedIn === true, "User must be logged in to logout");

    // State changes - using reactive signals with automatic sync
    user.value = {
      loggedIn: false,
      id: null,
      name: "Guest",
      role: "guest",
    };

    // Postconditions - verify state was reset
    ensures(user.value.loggedIn === false, "User must be logged out after logout");
    ensures(user.value.role === "guest", "User must have guest role after logout");

    return { success: true };
  });

  // Todo Management

  bus.on("TODO_ADD", (payload: { text: string; priority: "low" | "medium" | "high" }) => {
    // Preconditions - enforce configurable todo limit
    requires(hasLength(todos.value, { max: 99 }), "Cannot exceed 100 todos");
    requires(payload.text !== "", "Todo text must not be empty");

    // State change - using reactive signals with automatic sync
    // The priority parameter exercises parameter tracing for TLA+ generation
    const newTodo: Todo = {
      id: generateId(),
      text: payload.text,
      completed: false,
      priority: payload.priority,
      createdAt: Date.now(),
    };
    todos.value = [...todos.value, newTodo];

    // Postconditions - verify todo was added
    // Can't reference local variables (previousCount) in ensures() for TLA+ translation
    ensures(todos.value.length > 0, "Todos must not be empty after add");

    return { success: true, todo: newTodo };
  });

  bus.on("TODO_TOGGLE", (payload: { id: string }) => {
    // Precondition - todo must exist
    // TLA+ can't enumerate over sequences with \in, so we use length check as proxy
    requires(todos.value.length > 0, "Todos must not be empty to toggle");

    const todo = todos.value.find((t) => t.id === payload.id);
    if (todo) {
      // State change - using reactive signals with automatic sync
      todos.value = todos.value.map((t) =>
        t.id === payload.id ? { ...t, completed: !t.completed } : t
      );

      // Postcondition - verify todo count unchanged (toggle doesn't remove)
      ensures(todos.value.length > 0, "Todos must not be empty after toggle");

      // biome-ignore lint/style/noNonNullAssertion: todo exists after update
      const updatedTodo = todos.value.find((t) => t.id === payload.id)!;
      return { success: true, todo: updatedTodo };
    }

    return { success: false, error: "Todo not found" };
  });

  bus.on("TODO_REMOVE", (payload: { id: string }) => {
    // Precondition - todo must exist
    // TLA+ can't enumerate over sequences with \in, so we use length check as proxy
    requires(todos.value.length > 0, "Todos must not be empty to remove");

    // State change - using reactive signals with automatic sync
    todos.value = todos.value.filter((t) => t.id !== payload.id);

    // Postconditions - verify removal (length-based check for TLA+ compatibility)
    // Can't use .some() as TLA+ can't enumerate over sequences
    // The actual runtime check is done internally by filter()

    return { success: true };
  });

  bus.on("TODO_CLEAR_COMPLETED", () => {
    const completedCount = todos.value.filter((t) => t.completed).length;

    // State change - using reactive signals with automatic sync
    todos.value = todos.value.filter((t) => !t.completed);

    // Postconditions - verify operation completed
    // Can't use .some() as TLA+ can't enumerate over sequences
    // The actual runtime check is done internally by filter()

    return { success: true, removed: completedCount };
  });

  // Configuration

  bus.on("TODO_SET_LIMIT", (payload: { limit: number }) => {
    // Precondition - limit must be positive (exercises { type: "number" } verification)
    requires(payload.limit > 0, "Limit must be positive");

    // State change - update configurable limit
    maxTodos.value = payload.limit;

    return { success: true };
  });

  // Theme preference setter. Exercises payload-domain wiring (issue #72): the
  // extractor records assignments[].value = "param:theme", and the verifier
  // types payload.theme as the declared enum domain rather than the catch-all Value.
  bus.on("SET_THEME", (payload: { theme: "light" | "dark" | "system" }) => {
    theme.value = payload.theme;
    return { success: true };
  });

  // Queries

  bus.on("GET_STATE", () => {
    // Verification: ensure all todo IDs are unique
    const ids = todos.value.map((t) => t.id);
    const _uniqueIds = new Set(ids);

    // Return a deep copy to prevent reference sharing issues
    return {
      user: { ...user.value },
      todos: todos.value.map((t) => ({ ...t })),
      filter: filter.value,
    };
  });

  bus.on("GET_TODOS", (payload?: { filter?: "all" | "active" | "completed" }) => {
    const filterValue = payload?.filter || "all";

    let filteredTodos = todos.value;
    if (filterValue === "active") {
      filteredTodos = todos.value.filter((t) => !t.completed);
    } else if (filterValue === "completed") {
      filteredTodos = todos.value.filter((t) => t.completed);
    }

    return { todos: filteredTodos };
  });
}

// Background script entry point
import { createBackground } from "@fairfox/polly/background";
import type { TodoMessages } from "../shared/messages";
import { registerTodoHandlers } from "./handlers";

// The documented factory path: createBackground() wires the MessageBus +
// MessageRouter, then the shared composite helper registers the handlers. The
// BDD world (features/steps.ts) calls the same registerTodoHandlers() against a
// createBackground(createMockAdapters()) bus, so both cross the same boundary.
const bus = createBackground<TodoMessages>();
registerTodoHandlers(bus);

console.log("Todo List Extension: Background script initialized");

// Application state management using Polly's reactive state primitives
import { $sharedState } from "@fairfox/polly/state";
import type { Todo, User } from "../shared/types";

// Reactive state with automatic synchronization and persistence
export const user = $sharedState<User>("user", {
  id: null,
  name: "Guest",
  role: "guest",
  loggedIn: false,
});

export const todos = $sharedState<Todo[]>("todos", []);

export const filter = $sharedState<"all" | "active" | "completed">("filter", "all");

// Configurable todo limit (exercises { type: "number" } verification)
export const maxTodos = $sharedState<number>("maxTodos", 50);

// User-facing theme preference. Exercises payload-domain wiring (issue #72): the
// SET_THEME handler writes payload.theme into this signal directly, so the verifier
// types `payload.theme` as the declared enum domain.
export const theme = $sharedState<"light" | "dark" | "system">("theme", "system");

// Helper to generate IDs
export function generateId(): string {
  return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
}

