import type { AppState } from "./types/state";

type Handler = (payload: unknown) => void;

const handlers = new Map<string, Handler>();

const bus = {
  on(type: string, handler: Handler): void {
    handlers.set(type, handler);
  },
};

declare function requires(condition: boolean, message: string): void;
declare function ensures(condition: boolean, message: string): void;

export const state: AppState = {
  flag: false,
  literalTrue: true,
  role: "guest",
  inlineEnum: "off",
  count: 0,
  literalNumber: 42,
  label: "",
  literalString: "fixed",
  maybeName: null,
  nullableRole: null,
  mixed: 0,
  tags: [],
  profiles: [],
  matrix: [],
  byId: new Map(),
  seen: new Set(),
  record: {},
  nested: { inner: { depth: 0, mode: "a" }, list: [] },
  callback: () => undefined,
  anything: undefined,
  nothing: null,
};

bus.on("USER_LOGIN", () => {
  requires(state.role === "guest", "Must be a guest");
  state.role = "user";
  state.flag = true;
  state.count += 1;
  ensures(state.role === "user", "Must be a user");
});

bus.on("USER_LOGOUT", () => {
  state.role = "guest";
  state.flag = false;
  state.maybeName = null;
});

bus.on("SET_ROLE", () => {
  state.role = "admin";
  state.nested.inner.mode = "b";
});

// Message-type shapes findMessageTypes recognises, and some it only warns on.

export type SimpleMessage = "PING" | "PONG";

export type Discriminated =
  | { type: "USER_LOGIN"; userId: string }
  | { type: "USER_LOGOUT" }
  | { type: "SET_ROLE"; role: "admin" | "user" };

export type AliasOfAlias = SimpleMessage;

export type Composite = Discriminated | SimpleMessage | "RESET";

export type Keys = "OPEN" | "CLOSE";

export type Mapped = { [K in Keys]: { type: K } };

export type Templated = `EVENT_${string}`;

export type DiscriminatedTemplate = { type: `CMD_${number}` } | { type: "CMD_STOP" };

export type Conditional<T> = T extends string ? "STRING_MSG" : "OTHER_MSG";

// Every TypeInfo kind convertType distinguishes, nested and nullable.

export type Role = "admin" | "user" | "guest";

export type Profile = {
  name: string;
  age: number;
  verified: boolean;
};

export type AppState = {
  flag: boolean;
  literalTrue: true;
  role: Role;
  inlineEnum: "on" | "off";
  count: number;
  literalNumber: 42;
  label: string;
  literalString: "fixed";
  maybeName: string | null;
  optionalCount?: number;
  nullableRole: Role | null;
  mixed: string | number;
  tags: string[];
  profiles: Profile[];
  matrix: number[][];
  byId: Map<string, Profile>;
  seen: Set<number>;
  record: Record<string, boolean>;
  nested: {
    inner: {
      depth: number;
      mode: "a" | "b" | "c";
    };
    list: Array<"x" | "y">;
  };
  callback: () => void;
  anything: unknown;
  nothing: null;
};

