// State primitives with optional sync and persistence

import { effect, type Signal, signal } from "@preact/signals";
import { readNumber } from "./guards";
import type { MessageBus } from "./message-bus";
import { createStorageAdapter, type StorageAdapter } from "./storage-adapter";
import { createSyncAdapter, type StateSyncMessage, type SyncAdapter } from "./sync-adapter";

type StateEntry<T> = {
  signal: Signal<T>;
  clock: number; // Lamport clock for causal ordering
  loaded: Promise<void>;
  updating: boolean;
};

type StateOptions<T = unknown> = {
  // Legacy MessageBus support (deprecated, will be removed in v2.0)
  bus?: MessageBus;

  // New adapter system (recommended)
  storage?: StorageAdapter; // Custom storage adapter
  sync?: SyncAdapter; // Custom sync adapter

  // Behavior options
  debounceMs?: number; // Debounce storage writes
  validator?: (value: unknown) => value is T; // Runtime type validation
  verify?: boolean; // Enable verification tracking (creates plain object mirror)
};

const stateRegistry = new Map<string, StateEntry<unknown>>();

/**
 * Shared state: synced across all contexts AND persisted to storage
 *
 * Uses Lamport clock for conflict resolution. State is automatically:
 * - Loaded from chrome.storage on initialization
 * - Synced to other contexts via broadcast messages
 * - Persisted to chrome.storage on every change
 *
 * Available in: background, popup, options, devtools, content scripts
 * ⚠️ NOT available in page scripts (use content script state instead)
 *
 * @param key - Unique identifier for this state (e.g., "app-settings")
 * @param initialValue - Default value if nothing is in storage
 * @param options - Optional configuration (bus, debounceMs)
 * @returns Reactive signal that stays in sync across all contexts
 *
 * @example
 * ```typescript
 * // Define once, use everywhere
 * const settings = $sharedState("settings", { theme: "dark" })
 *
 * // Changes automatically sync
 * settings.value = { theme: "light" }
 * ```
 */
export function $sharedState<T>(
  key: string,
  initialValue: T,
  options: StateOptions<T> = {}
): Signal<T> & { loaded: Promise<void>; verify?: T } {
  const entry = createState(key, initialValue, {
    ...options,
    enableSync: true,
    enablePersist: true,
  });

  // Expose loaded promise for awaiting hydration
  return Object.assign(entry.signal, { loaded: entry.loaded });
}

/**
 * Synced state: synced across all contexts but NOT persisted
 *
 * State is broadcast to all contexts in real-time but resets on extension reload.
 *
 * Available in: background, popup, options, devtools, content scripts
 * ⚠️ NOT available in page scripts
 *
 * @param key - Unique identifier for this state
 * @param initialValue - Default value
 * @param options - Optional configuration
 * @returns Reactive signal synced across contexts (but not persisted)
 *
 * @example
 * ```typescript
 * // Temporary shared state
 * const activeTabId = $syncedState("active-tab", null)
 * ```
 */
export function $syncedState<T>(
  key: string,
  initialValue: T,
  options: StateOptions<T> = {}
): Signal<T> {
  return createState(key, initialValue, {
    ...options,
    enableSync: true,
    enablePersist: false,
  }).signal;
}

/**
 * Persisted state: persisted to storage but NOT synced across contexts
 *
 * Each context has its own copy of the state, persisted independently.
 *
 * Available in: background, popup, options, devtools, content scripts
 * ⚠️ NOT available in page scripts
 *
 * @param key - Unique identifier (use prefix like "popup:state" to avoid collisions)
 * @param initialValue - Default value
 * @param options - Optional configuration
 * @returns Reactive signal persisted to storage (but not synced)
 *
 * @example
 * ```typescript
 * // Each context has its own persisted state
 * const popupState = $persistedState("popup:last-panel", "home")
 * const devtoolsState = $persistedState("devtools:expanded", true)
 * ```
 */
export function $persistedState<T>(
  key: string,
  initialValue: T,
  options: StateOptions<T> = {}
): Signal<T> & { loaded: Promise<void> } {
  const entry = createState(key, initialValue, {
    ...options,
    enableSync: false,
    enablePersist: true,
  });

  // Expose loaded promise for awaiting hydration
  return Object.assign(entry.signal, { loaded: entry.loaded });
}

/**
 * Local state: not synced, not persisted (like regular Preact signal)
 *
 * Simple reactive state that lives only in the current context.
 * Resets on reload or context restart.
 *
 * Available in: all contexts (including page scripts)
 *
 * @param initialValue - Default value
 * @returns Reactive signal (local only)
 *
 * @example
 * ```typescript
 * // Local UI state
 * const isLoading = $state(false)
 * const error = $state<string | null>(null)
 * ```
 */
export function $state<T>(initialValue: T): Signal<T> {
  return signal(initialValue);
}

/** Server-side authoritative state, keyed for stable identity across the
 *  process. Unlike the browser primitives it does NOT sync across contexts or
 *  persist to chrome.storage — the server holds the canonical replica and is
 *  the always-on peer; connected clients receive derived updates through the
 *  Elysia `polly()` plugin's effect/broadcast layer rather than through this
 *  signal directly. Used inside `polly({ state: { server: { ... } } })` and
 *  read on the request context as `pollyState.server.<key>.value`. */
const serverStateRegistry = new Map<string, Signal<unknown>>();

/**
 * Reactive server-only state. The first call for a `key` creates the signal;
 * later calls with the same `key` return that same signal, so a module that
 * declares its server state once gets a stable reference everywhere it is
 * read.
 *
 * @param key - Stable identifier for this server state (e.g. "db")
 * @param initialValue - Value held until the server mutates it
 * @returns A reactive signal holding the authoritative server value
 *
 * @example
 * ```typescript
 * import { $serverState } from "@fairfox/polly";
 *
 * const db = { todos: signal([]), nextId: 1 };
 * polly({ state: { server: { db: $serverState("db", db) } } });
 * // in a handler: ctx.pollyState.server.db.value.todos.value = [...]
 * ```
 */
export function $serverState<T>(key: string, initialValue: T): Signal<T> {
  const existing = serverStateRegistry.get(key);
  // The registry erases T (it stores Signal<unknown>); the key is the
  // caller's contract that the stored signal carries their T.
  if (existing) return existing as unknown as Signal<T>;
  const sig = signal(initialValue);
  serverStateRegistry.set(key, sig);
  return sig;
}

type InternalStateOptions<T = unknown> = StateOptions<T> & {
  enableSync: boolean; // Whether to enable sync (avoid collision with sync?: SyncAdapter)
  enablePersist: boolean; // Whether to enable persistence
};

// Deep equality check to prevent redundant updates
export function deepEqual(a: unknown, b: unknown): boolean {
  if (a === b) return true;
  if (a == null || b == null) return false;
  if (typeof a !== "object" || typeof b !== "object") return false;

  const entriesA = Object.entries(a);
  const valuesB = new Map<string, unknown>(Object.entries(b));

  if (entriesA.length !== valuesB.size) return false;

  for (const [key, value] of entriesA) {
    if (!valuesB.has(key)) return false;
    if (!deepEqual(value, valuesB.get(key))) return false;
  }

  return true;
}

/**
 * Resolve storage and sync adapters with three-tier priority:
 * 1. Explicit adapters from options (highest priority)
 * 2. MessageBus adapters (legacy, deprecated)
 * 3. Auto-detected adapters (default behavior)
 */
function resolveAdapters(options: InternalStateOptions): {
  storage: StorageAdapter | null;
  sync: SyncAdapter | null;
} {
  // Priority 1: Explicit adapters (partial or full)
  if (options.storage || options.sync) {
    return {
      storage: options.storage || (options.enablePersist ? createStorageAdapter() : null),
      sync: options.sync || (options.enableSync ? createSyncAdapter() : null),
    };
  }

  // Priority 2: MessageBus (legacy support)
  // MessageBus doesn't provide sync adapter, only Chrome storage
  if (options.bus) {
    return {
      storage: options.bus.adapters.storage,
      sync: options.enableSync ? createSyncAdapter() : null,
    };
  }

  // Priority 3: Auto-detect based on enableSync and enablePersist flags
  return {
    storage: options.enablePersist ? createStorageAdapter() : null,
    sync: options.enableSync ? createSyncAdapter() : null,
  };
}

function createState<T>(
  key: string,
  initialValue: T,
  options: InternalStateOptions<T>
): StateEntry<T> {
  // Return existing entry if already registered
  const existing = stateRegistry.get(key);
  if (existing) {
    // The registry erases T (it stores StateEntry<unknown>); the key is the
    // caller's contract that the stored entry carries their T.
    return existing as unknown as StateEntry<T>;
  }

  const sig = signal(initialValue);

  // Create verification mirror if requested. The effect below updates the
  // mirror in place; `sig.verify` exposes it to verification tooling.
  let mirror: T | undefined;
  if (options.verify) {
    // Create plain object mirror for verification
    const copy: unknown = JSON.parse(JSON.stringify(initialValue));
    // cast: a JSON round trip of a T; the verification mirror is plain data
    mirror = copy as T;
    // nosemgrep: javascript.lang.security.insecure-object-assign.insecure-object-assign — one constant key; the value is a JSON clone of the caller's own initial value.
    Object.assign(sig, { verify: mirror });
  }

  const entry: StateEntry<T> = {
    signal: sig,
    clock: 0,
    loaded: Promise.resolve(),
    updating: false,
  };

  // Resolve adapters (explicit, MessageBus, or auto-detect)
  const adapters = resolveAdapters(options);

  // Load from storage if persist is enabled
  if (options.enablePersist && adapters.storage) {
    entry.loaded = loadFromStorage(key, sig, entry, adapters.storage, options.validator);
  }

  // polly#167: the pending debounce timer lives in createState scope, not
  // inside the `loaded` callback, because the incoming-message handler below
  // has to be able to cancel a write the message supersedes.
  let debounceTimer: NodeJS.Timeout | null = null;

  // Watch for changes after initial load
  entry.loaded.then(() => {
    let previousValue = sig.value;
    let isFirstRun = true;

    // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Sync effect requires coordination of multiple state change scenarios
    effect(() => {
      // Read the signal FIRST, before any early return can happen.
      //
      // Preact re-collects an effect's dependencies on every run, so a run that
      // returns without touching `sig.value` unsubscribes the effect for good.
      // The run an incoming sync message triggers is exactly such a run.
      const value = sig.value;

      // Skip first run (effect fires immediately on registration)
      if (isFirstRun) {
        isFirstRun = false;
        return;
      }

      // An incoming message is being applied. Adopt it as the baseline — this
      // context now holds it, so the next local change is a change against it —
      // and do not broadcast, which would echo it back to the sender.
      if (entry.updating) {
        previousValue = value;
        return;
      }

      // Skip if value hasn't changed (deep equality check)
      if (deepEqual(value, previousValue)) {
        return;
      }

      previousValue = value;

      // Update verification mirror if enabled
      if (mirror) {
        // nosemgrep: javascript.lang.security.insecure-object-assign.insecure-object-assign — internal mirror; value is a deep JSON clone, not arbitrary external input.
        Object.assign(mirror, JSON.parse(JSON.stringify(value)));
      }

      // Increment clock monotonically
      entry.clock++;

      // polly#167: bind the clock to the value HERE, where the two agree.
      //
      // `doUpdate` used to read `entry.clock` when it fired. Under
      // `debounceMs` that is a later moment, and the incoming-message handler
      // below raises `entry.clock` to any message's clock — including a
      // message whose value it rejects. So the deferred write paired this
      // value with somebody else's clock, persisted the pair, and broadcast
      // it. The persisted clock is restored on the next load, so a peer
      // re-sending the real value at that clock was then refused by the
      // strictly-greater rule and the divergence became durable.
      const clockAtWrite = entry.clock;

      const doUpdate = () => {
        debounceTimer = null;

        // Persist to storage
        if (options.enablePersist && adapters.storage) {
          persistToStorage(key, value, clockAtWrite, adapters.storage);
        }

        // Broadcast to other contexts
        if (options.enableSync && adapters.sync) {
          broadcastUpdate(key, value, clockAtWrite, adapters.sync);
        }
      };

      // Debounce if specified
      if (options.debounceMs) {
        if (debounceTimer) clearTimeout(debounceTimer);
        debounceTimer = setTimeout(doUpdate, options.debounceMs);
      } else {
        doUpdate();
      }
    });
  });

  // Listen for updates from other contexts (only if sync enabled)
  if (options.enableSync && adapters.sync) {
    // Connect if needed (some adapters require explicit connection)
    if (adapters.sync.connect) {
      adapters.sync.connect();
    }

    /**
     * Take an incoming value this context has decided to accept.
     *
     * polly#167 put two steps in front of the apply. Both are about a pending
     * debounce timer that the message has just made wrong.
     */
    const acceptIncoming = (value: T, clock: number): void => {
      // The local value is causally older than this one, so the deferred write
      // has nothing left to say. Dropping it stops a stale broadcast that a
      // third context still below this clock would accept.
      //
      // Reached only for a value this context does not already hold: the
      // deep-equality skip below returns first, which leaves a pending timer
      // holding that same value armed, as it should be.
      if (debounceTimer) {
        clearTimeout(debounceTimer);
        debounceTimer = null;
      }

      applyUpdate(entry, value, clock);

      // `applyUpdate` sets `entry.updating`, so the local effect returns
      // without writing. Persist the incoming pair here, or storage keeps
      // whatever it last held while the signal holds this value — and on the
      // next load the two disagree.
      if (options.enablePersist && adapters.storage) {
        persistToStorage(key, value, clock, adapters.storage);
      }
    };

    /** Whether an incoming value is one this context should take. */
    const shouldAccept = (message: StateSyncMessage<T>): boolean => {
      // Validate incoming value if validator provided
      if (options.validator && !options.validator(message.value)) {
        console.warn(
          `[Polly] State "${key}": Received invalid value from sync (clock: ${message.clock})`,
          message.value
        );
        return false;
      }

      // Skip redundant updates (deep equality check)
      return !deepEqual(entry.signal.value, message.value);
    };

    // Register sync message listener
    adapters.sync.onMessage<T>((message) => {
      if (message.key !== key) return;

      const oldClock = entry.clock;

      // Lamport clock rule: Always update to max(local, received)
      // This maintains causal ordering even when rejecting updates
      entry.clock = Math.max(entry.clock, message.clock);

      // Only accept value updates if received clock is strictly greater than old local clock
      // This ensures we only apply causally newer updates
      if (message.clock > oldClock && shouldAccept(message)) {
        acceptIncoming(message.value, message.clock);
      }
    });
  }

  stateRegistry.set(key, entry);
  return entry;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Backfill keys added to the state shape since a value was persisted.
 *
 * Stored plain objects are shallow-merged over the current defaults so that a
 * field added in a later release rehydrates to its default rather than
 * `undefined`. Primitives and arrays are replaced wholesale — merging those
 * would corrupt them.
 */
function reconcileWithDefaults<T>(defaults: T, stored: unknown): T {
  // Persisted values are trusted to be the T this key was registered with;
  // schema drift is handled by the merge, not by runtime validation.
  if (isPlainObject(defaults) && isPlainObject(stored)) {
    return { ...defaults, ...stored };
  }
  // cast: a persisted value is trusted to be the T its key was registered with
  return stored as T;
}

async function loadFromStorage<T>(
  key: string,
  sig: Signal<T>,
  entry: StateEntry<T>,
  storage: StorageAdapter,
  validator?: (value: unknown) => value is T
): Promise<void> {
  try {
    const result = await storage.get([key, `${key}:clock`]);

    if (result[key] !== undefined) {
      // sig still holds the initial value here, so it is the default base
      // for backfilling keys the persisted blob predates.
      const storedValue = reconcileWithDefaults(sig.peek(), result[key]);

      // Validate stored value if validator provided
      if (validator) {
        if (validator(storedValue)) {
          sig.value = storedValue;
        } else {
          console.warn(
            `[Polly] State "${key}": Stored value failed validation, using initial value`,
            storedValue
          );
        }
      } else {
        sig.value = storedValue;
      }
    }

    const storedClock = readNumber(result[`${key}:clock`]);
    if (storedClock !== undefined) {
      entry.clock = storedClock;
    }
  } catch (error) {
    console.warn(`[Polly] Failed to load state from storage: ${key}`, error);
  }
}

function persistToStorage<T>(key: string, value: T, clock: number, storage: StorageAdapter): void {
  try {
    storage.set({
      [key]: value,
      [`${key}:clock`]: clock,
    });
  } catch (error) {
    console.warn(`[Polly] Failed to persist state to storage: ${key}`, error);
  }
}

function broadcastUpdate<T>(key: string, value: T, clock: number, sync: SyncAdapter): void {
  try {
    sync.broadcast({
      key,
      value,
      clock,
    });
  } catch (error) {
    console.warn(`[Polly] Failed to broadcast state update: ${key}`, error);
  }
}

function applyUpdate<T>(entry: StateEntry<T>, value: T, clock: number): void {
  entry.updating = true;
  entry.signal.value = value;
  entry.clock = clock;
  entry.updating = false;
}

/**
 * Get state by key (useful for retrieving state without re-creating)
 */
export function getStateByKey<T>(key: string): Signal<T> | undefined {
  const entry = stateRegistry.get(key);
  return entry?.signal as unknown as Signal<T> | undefined;
}

/**
 * Clear state registry (useful for testing)
 */
export function clearStateRegistry(): void {
  stateRegistry.clear();
}

