// Type definitions for all messages in the extension

/**
 * Base message interface that all messages must satisfy.
 * This allows users to define custom messages alongside framework messages.
 */
export interface BaseMessage {
  type: string;
}

export type Context =
  | "background"
  | "content"
  | "page"
  | "devtools"
  | "popup"
  | "options"
  | "sidepanel"
  | "offscreen";

// All contexts (useful for broadcast)
export const ALL_CONTEXTS: Context[] = [
  "background",
  "content",
  "page",
  "devtools",
  "popup",
  "options",
  "sidepanel",
  "offscreen",
] as const;

// Settings schema
export type Settings = {
  theme: "light" | "dark" | "auto";
  autoSync: boolean;
  debugMode: boolean;
  notifications: boolean;
  apiEndpoint: string;
  refreshInterval: number;
};

export const defaultSettings: Settings = {
  theme: "auto",
  autoSync: true,
  debugMode: false,
  notifications: true,
  apiEndpoint: "https://api.example.com",
  refreshInterval: 60000,
};

// Logging types
export type LogLevel = "debug" | "info" | "warn" | "error";

export type LogEntry = {
  id: string;
  level: LogLevel;
  message: string;
  context?: Record<string, unknown>;
  error?: string;
  stack?: string;
  source: Context;
  timestamp: number;
};

// All possible messages (discriminated union)
export type ExtensionMessage =
  // DOM Operations (handled by Content Script)
  | { type: "DOM_QUERY"; selector: string }
  | { type: "DOM_UPDATE"; selector: string; content: string }
  | {
      type: "DOM_INSERT";
      position: "beforebegin" | "afterbegin" | "beforeend" | "afterend";
      html: string;
    }
  | { type: "DOM_REMOVE"; selector: string }

  // Page Script Operations (handled by Page Script)
  | { type: "PAGE_GET_VAR"; varName: string }
  | { type: "PAGE_CALL_FN"; fnName: string; args: unknown[] }
  | { type: "PAGE_SET_VAR"; varName: string; value: unknown }

  // API Operations (handled by Background)
  | {
      type: "API_REQUEST";
      endpoint: string;
      method: "GET" | "POST" | "PUT" | "DELETE";
      body?: unknown;
      headers?: Record<string, string>;
    }
  | {
      type: "API_BATCH";
      requests: Array<{ endpoint: string; method: string; body?: unknown }>;
    }

  // Clipboard Operations (handled by Offscreen)
  | { type: "CLIPBOARD_WRITE"; text: string }
  | { type: "CLIPBOARD_WRITE_HTML"; html: string }
  | { type: "CLIPBOARD_WRITE_RICH"; data: { text: string; html: string } }
  | { type: "CLIPBOARD_READ" }

  // Context Menu (handled by Background)
  | {
      type: "CONTEXT_MENU_CLICKED";
      menuId: string;
      info: chrome.contextMenus.OnClickData;
      tabId: number;
    }
  | {
      type: "CONTEXT_MENU_CREATE";
      id: string;
      title: string;
      contexts: chrome.contextMenus.ContextType[];
    }
  | { type: "CONTEXT_MENU_REMOVE"; id: string }

  // State Sync (broadcast) - Internal only, handled by state primitives
  | {
      type: "STATE_SYNC";
      key: string;
      value: unknown;
      clock: number;
    }

  // Tab Operations (handled by Background)
  | { type: "TAB_QUERY"; queryInfo: chrome.tabs.QueryInfo }
  | { type: "TAB_GET_CURRENT" }
  | { type: "TAB_RELOAD"; tabId: number }

  // DevTools Operations
  | { type: "DEVTOOLS_INSPECT_ELEMENT"; selector: string }
  | {
      type: "DEVTOOLS_LOG";
      level: "log" | "warn" | "error";
      message: string;
      data?: unknown;
    }

  // Logging (handled by Background LogStore)
  | {
      type: "LOG";
      level: LogLevel;
      message: string;
      context?: Record<string, unknown>;
      error?: string;
      stack?: string;
      source: Context;
      timestamp: number;
    }
  | {
      type: "LOGS_GET";
      filters?: {
        level?: LogLevel;
        source?: Context;
        since?: number;
        limit?: number;
      };
    }
  | { type: "LOGS_CLEAR" }
  | { type: "LOGS_EXPORT" }

  // Test Messages (only used in tests)
  | { type: "TEST_MESSAGE"; data?: unknown }
  | { type: "TEST"; iteration?: number }
  | { type: "CUSTOM_MESSAGE"; data?: unknown }
  | { type: "SETTINGS_GET" }
  | {
      type: "SIGNAL_UPDATE";
      key?: string;
      value?: unknown;
      signalId?: string;
      source?: Context;
    }
  | {
      type: "USER_DATA";
      password?: string;
      apiKey?: string;
      [key: string]: unknown;
    };

// Helper: Look up the full message type from a union based on the 'type' discriminator
type LookupMessage<TUnion, TType extends string> = TUnion extends { type: TType } ? TUnion : never;

// Extract response type from message using phantom type
// If message has __response field (phantom type), use it; otherwise infer from framework messages
export type MessageResponse<T extends BaseMessage> =
  // First, try to find the matching message in the union by type discriminator
  T extends { type: infer TType extends string }
    ? LookupMessage<T, TType> extends { readonly __response?: infer R }
      ? R // Found phantom type, use it
      : T extends ExtensionMessage
        ? // Framework message - infer from type
          // DOM Operations
          T extends { type: "DOM_QUERY" }
          ? {
              elements: Array<{
                tag: string;
                text: string;
                html: string;
                attrs: Record<string, string>;
                rect?: DOMRect;
              }>;
            }
          : T extends { type: "DOM_UPDATE" }
            ? { success: boolean }
            : T extends { type: "DOM_INSERT" }
              ? { success: boolean }
              : T extends { type: "DOM_REMOVE" }
                ? { success: boolean; count: number }
                : // Page Script Operations
                  T extends { type: "PAGE_GET_VAR" }
                  ? { value: unknown; exists: boolean }
                  : T extends { type: "PAGE_CALL_FN" }
                    ? { result: unknown; error?: string }
                    : T extends { type: "PAGE_SET_VAR" }
                      ? { success: boolean }
                      : // API Operations
                        T extends { type: "API_REQUEST" }
                        ? {
                            data: unknown;
                            status: number;
                            statusText: string;
                            headers: Record<string, string>;
                            error?: string;
                          }
                        : T extends { type: "API_BATCH" }
                          ? {
                              results: Array<{
                                data: unknown;
                                status: number;
                                error?: string;
                              }>;
                            }
                          : // Clipboard Operations
                            T extends { type: "CLIPBOARD_WRITE" }
                            ? { success: boolean }
                            : T extends { type: "CLIPBOARD_WRITE_HTML" }
                              ? { success: boolean }
                              : T extends { type: "CLIPBOARD_WRITE_RICH" }
                                ? { success: boolean }
                                : T extends { type: "CLIPBOARD_READ" }
                                  ? { text: string }
                                  : // Context Menu
                                    T extends { type: "CONTEXT_MENU_CLICKED" }
                                    ? undefined
                                    : T extends { type: "CONTEXT_MENU_CREATE" }
                                      ? { success: boolean }
                                      : T extends { type: "CONTEXT_MENU_REMOVE" }
                                        ? { success: boolean }
                                        : // State Sync
                                          T extends { type: "STATE_SYNC" }
                                          ? undefined
                                          : // Tab Operations
                                            T extends { type: "TAB_QUERY" }
                                            ? { tabs: chrome.tabs.Tab[] }
                                            : T extends {
                                                  type: "TAB_GET_CURRENT";
                                                }
                                              ? { tab: chrome.tabs.Tab }
                                              : T extends {
                                                    type: "TAB_RELOAD";
                                                  }
                                                ? { success: boolean }
                                                : // DevTools Operations
                                                  T extends {
                                                      type: "DEVTOOLS_INSPECT_ELEMENT";
                                                    }
                                                  ? {
                                                      success: boolean;
                                                    }
                                                  : T extends {
                                                        type: "DEVTOOLS_LOG";
                                                      }
                                                    ? undefined
                                                    : // Logging Operations
                                                      T extends {
                                                          type: "LOG";
                                                        }
                                                      ? {
                                                          success: boolean;
                                                        }
                                                      : T extends {
                                                            type: "LOGS_GET";
                                                          }
                                                        ? {
                                                            logs: LogEntry[];
                                                          }
                                                        : T extends {
                                                              type: "LOGS_CLEAR";
                                                            }
                                                          ? {
                                                              success: boolean;
                                                              count: number;
                                                            }
                                                          : T extends {
                                                                type: "LOGS_EXPORT";
                                                              }
                                                            ? {
                                                                json: string;
                                                                count: number;
                                                              }
                                                            : T extends {
                                                                  type: "SETTINGS_GET";
                                                                }
                                                              ? {
                                                                  settings: unknown;
                                                                }
                                                              : undefined
        : unknown // For custom messages outside ExtensionMessage, require phantom type
    : unknown; // Fallback for messages without type field

// Message handler mapping (which context handles which message)
// Can be a single context or an array for multi-target routing
export type MessageHandler = {
  DOM_QUERY: "content";
  DOM_UPDATE: "content";
  DOM_INSERT: "content";
  DOM_REMOVE: "content";

  PAGE_GET_VAR: "page";
  PAGE_CALL_FN: "page";
  PAGE_SET_VAR: "page";

  API_REQUEST: "background";
  API_BATCH: "background";

  CLIPBOARD_WRITE: "offscreen";
  CLIPBOARD_WRITE_HTML: "offscreen";
  CLIPBOARD_WRITE_RICH: "offscreen";
  CLIPBOARD_READ: "offscreen";

  CONTEXT_MENU_CLICKED: "background";
  CONTEXT_MENU_CREATE: "background";
  CONTEXT_MENU_REMOVE: "background";

  STATE_SYNC: Context[]; // Broadcast to all contexts

  TAB_QUERY: "background";
  TAB_GET_CURRENT: "background";
  TAB_RELOAD: "background";

  DEVTOOLS_INSPECT_ELEMENT: "content";
  DEVTOOLS_LOG: "background";

  LOG: "background";
  LOGS_GET: "background";
  LOGS_CLEAR: "background";
  LOGS_EXPORT: "background";
};

// Routed message envelope
export type RoutedMessage<T extends BaseMessage = ExtensionMessage> = {
  id: string; // Correlation ID (UUID)
  source: Context; // Which context sent it
  targets: Context[]; // Which contexts should receive this (can be multiple)
  tabId?: number; // Required for per-tab contexts
  timestamp: number; // When it was sent
  payload: T; // The actual message
};

// Routed response envelope
export type RoutedResponse<T extends BaseMessage = ExtensionMessage> = {
  id: string; // Matches request ID
  success: boolean; // Whether operation succeeded
  data?: MessageResponse<T>; // Response data
  error?: string; // Error message if failed
  timestamp: number; // When response was sent
};

/**
 * Drive a real polly MessageBus from step definitions.
 *
 * `createBackground()` wires a MessageRouter whose request/response loopback
 * runs over ports — which don't exist in a single in-process world, so a
 * self-targeted `bus.send` would just time out. `handleMessage` is the exact
 * method the router calls for a background-targeted message
 * (`routeToSingleTarget` → `this.bus.handleMessage(message)`): it runs the
 * registered handler and returns its response. So we build the inbound
 * RoutedMessage a UI context would send and hand it to `handleMessage`.
 *
 * This crosses the real handler + state-signal path through the real,
 * factory-built bus. The only thing it does NOT exercise is cross-context port
 * transport — and that boundary is covered for real by the mesh e2e scenario,
 * not faked here. (The polly#57 lesson is about not letting a hand-wired bus
 * paper over a factory gap; here the factory built the bus and registered the
 * handlers, and we drive its own dispatch entry point.)
 */
import { readRecord } from "../../../src/shared/lib/guards";
import type { BusLike } from "./types.ts";

/**
 * Anything with the bus's dispatch entry point. Declared as a *method* (not an
 * arrow property) so its parameter is bivariant — a real
 * `MessageBus<TMessage>`, whose `handleMessage` takes the narrower
 * `RoutedMessage<TMessage>`, is assignable here.
 */
export interface DispatchBus {
  handleMessage(message: unknown): Promise<unknown>;
}

interface DriveOptions {
  /** The context the message appears to come from (a UI context → background). */
  source?: string;
  /** Default delivery target. */
  target?: string;
}

export function driveBus(bus: DispatchBus, driveOpts: DriveOptions = {}): BusLike {
  const source = driveOpts.source ?? "popup";
  const defaultTarget = driveOpts.target ?? "background";

  return {
    async send(payload, options) {
      const target = options?.target ?? defaultTarget;
      const targets = Array.isArray(target) ? target : [target];
      const message = {
        id: crypto.randomUUID(),
        source,
        targets,
        timestamp: Date.now(),
        payload,
        ...(options?.tabId === undefined ? {} : { tabId: options.tabId }),
      };
      // The response is `{ success, data?, error? }`. Return the handler's own
      // return value (response.data); steps assert on it.
      const response: unknown = await bus.handleMessage(message);
      return readRecord(response)?.["data"];
    },
  };
}

